if(!$errors){$paths=store_uploaded_images($uploads);$status=is_admin()?'approved':((setting('enable_moderation','1')==='1'&&setting('auto_approve_content','0')!=='1')?'pending':'approved');$cover=$paths[0]??$gem['cover_image'];db()->beginTransaction();$stmt=db()->prepare('UPDATE gems SET title=?,description=?,location=?,city=?,vibes=?,budget_level=?,activity_type=?,operating_hours=?,cover_image=?,status=?,rejection_reason=NULL,approved_at=? WHERE id=?');$stmt->execute([$title,$description,$location,$city,implode(',',array_slice($vibes,0,3)),$budget,$activity,$hours?:'All Day',$cover,$status,$status==='approved'?date('Y-m-d H:i:s'):null,$id]);foreach($paths as $i=>$path){$stmt=db()->prepare('INSERT INTO gem_images(gem_id,image_path,alt_text,sort_order) VALUES(?,?,?,?)');$stmt->execute([$id,$path,$title,$i+10]);}db()->commit();flash('success',is_admin()?'Gem updated.':'Changes saved and submitted for approval.');redirect(is_admin()?'admin/moderation.php':'profile.php?tab=posted');}}
